from pathlib import Path
import json,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
H=Path(__file__).resolve().parent;O=H/'rgb_complete_goal_current_run';d=json.loads((H/'rgb_complete_goal_assessment.json').read_text());ss=json.loads((O/'states.json').read_text());task=json.loads((O/'task_episode.json').read_text());xy=np.array([s['position'][:2] for s in ss]);t=np.array([s['time_s'] for s in ss]);goal=np.array(task['original_episode']['goal_position_world_m'][:2]);start=np.array(task['original_episode']['start_position_world_m'][:2]);u=(goal-start)/np.linalg.norm(goal-start);r=json.loads((O/'policy_records.json').read_text());shadow=json.loads((O/'shadow_records.json').read_text());occ=np.load(O/'offline_occupancy_label.npz')
fig,ax=plt.subplots(1,3,figsize=(15,4.8));labels=occ['labels'];o=occ['origin'];res=float(occ['resolution']);ax[0].imshow(labels.T,origin='lower',extent=[o[0],o[0]+labels.shape[0]*res,o[1],o[1]+labels.shape[1]*res],cmap='Greys',alpha=.3);ax[0].plot(xy[:,0],xy[:,1],color='tab:blue');ax[0].scatter(*start,c='black',label='start');ax[0].scatter(*goal,marker='*',c='green',label='original goal');ax[0].set(xlim=(-4,4),ylim=(-4,4),title='Actual primary trajectory\noffline map background only',xlabel='world X(m)',ylabel='world Y(m)');ax[0].set_aspect('equal');ax[0].legend()
